#!/usr/bin/env python3
"""Build the item bank `generated-echoes-v1` (plan node V5): REAL echoes, generated by the tool.

    python3 make_bank.py        writes items.json, key.json, item_flags.json here, then runs ../../build_html.py --bank .
                                and puts the material hash it prints into key.json

Every item is a Rule line that slice/'s compiler accepts, with an echo produced by the compiler's own echo generator:

  faithful    the echo of the sentence's own composition tree, exactly as the tool prints it
  unfaithful  the echo of that tree after ONE mechanical mutation (mutate.py), shown against the ORIGINAL sentence

No sentence appears twice and no two items share an echo. Which sentences are mutated, and how, is fixed by hand in selection.json (so that each of the
five mutation kinds has three items and no mutant is equivalent to its original); the explanation and the disagreeing
case of each mutant are hand-written by the bank builder (a model). selection.json gives the key away and is git-ignored
like key.json. Item order is a seeded shuffle; ids are assigned after it.

Reads slice/ only through the scratch copy trials/sentences/work/slice (made by slice/mutation/workcopy.sh).
"""
import hashlib
import json
import random
import subprocess
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
import mutate          # noqa: E402
import pool as poolmod  # noqa: E402

BANK = "wallet-ledger-generated-echoes-v1"
SEED = 20261111

# Which sentences are in the bank, which are mutated and how, and the hand-written explanations: selection.json.
# That file is the key in another form, so it is kept out of this script and out of version control (.gitignore here).
SEL = json.loads((HERE / "selection.json").read_text())
MUTANTS = {m["sentence_begins"]: (m["kind"], m["what"], m["disagreeing_case"]) for m in SEL["mutants"]}
FAITHFUL = SEL["faithful"]
FLAGS = {f["sentence_begins"]: (f["severity"], f["note"]) for f in SEL["flags"]}


def find(sentences, start, exact_ok=True):
    hits = [s for s in sentences if s["text"] == start] or [s for s in sentences if s["text"].startswith(start)]
    if len(hits) != 1:
        # several sentences share the beginning: the shortest one is meant unless a longer beginning is given
        hits = sorted(hits, key=lambda s: len(s["text"]))[:1] if hits else hits
    assert len(hits) == 1, (start, [h["text"] for h in hits])
    return hits[0]


def main():
    sentences = poolmod.pool()
    voc_sha = hashlib.sha256((mutate.SENT / "work" / "slice" / "vocabulary.yaml").read_bytes()).hexdigest()
    real_voc = mutate.SENT.parents[1] / "slice" / "vocabulary.yaml"
    assert hashlib.sha256(real_voc.read_bytes()).hexdigest() == voc_sha, "the scratch copy's vocabulary differs from slice/vocabulary.yaml"
    rows, used = [], set()
    for start, (kind, what, case) in MUTANTS.items():
        s = find(sentences, start)
        assert s["text"] not in used, s["text"]
        used.add(s["text"])
        own = mutate.faithful_echo(s["text"])
        echo, change = mutate.mutated_echo(s["text"], kind)
        assert echo and echo != own, (start, kind)
        rows.append({"first": s["text"], "second": echo, "faithful": False, "error_kind": kind, "structure": "single-piece",
                     "explanation": f"Mutated tree ({change}). {what} Disagreeing case: {case}", "source": s["source"], "mutation": change,
                     "unmutated_echo": own})
    for start in FAITHFUL:
        s = find(sentences, start)
        assert s["text"] not in used, s["text"]
        used.add(s["text"])
        own = mutate.faithful_echo(s["text"])
        assert own, start
        rows.append({"first": s["text"], "second": own, "faithful": True, "error_kind": "none", "structure": None,
                     "explanation": "Unmutated: the echo the tool generates for this sentence's own composition tree. Keyed faithful BY CONSTRUCTION, "
                                    "not by a person's judgement: a reader who flags it has either raised a false alarm or found something in the "
                                    "tool's reading (see item_flags.json).", "source": s["source"], "mutation": None})
    echoes = [r["second"] for r in rows]
    assert len(set(echoes)) == len(echoes), "two items share an echo: a reader could tell that one of them is wrong"
    random.Random(SEED).shuffle(rows)
    items, key, flags = [], {}, {}
    for n, r in enumerate(rows, 1):
        i = f"E{n:02d}"
        items.append({"id": i, "kind": "echo", "first": r["first"], "second": r["second"]})
        key[i] = {k: r[k] for k in ("faithful", "error_kind", "structure", "explanation", "source", "mutation")}
        if not r["faithful"]:
            key[i]["unmutated_echo"] = r["unmutated_echo"]
        for start, (sev, note) in FLAGS.items():
            if r["faithful"] and find(sentences, start)["text"] == r["first"]:
                flags[i] = {"severity": sev, "note": note}
    assert len(flags) == len(FLAGS), (len(flags), len(FLAGS))
    material = {
        "schema": "meaning-trial-items-v1", "bank": BANK,
        "title": "Meaning trial V5: wallet and ledger, the tool's own echoes",
        "brief_file": "brief.md",
        "instructions": "For each item decide whether the ECHO says exactly the same thing as the RULE: no more, no less. Some do and some do not. "
                        "Judge every item on its own. What the brief calls a default or a fixed convention is not a difference.",
        "judgements": ["faithful", "not-faithful"],
        "parts": [{"kind": "echo", "title": "Rules and echoes", "first_label": "RULE", "second_label": "ECHO",
                   "question": "Each item has an English RULE and the tool's ECHO of how it understood the rule. Is the echo a faithful reading of the rule?"}],
        "items": items,
    }
    (HERE / "items.json").write_text(json.dumps(material, indent=1, ensure_ascii=False) + "\n")
    out = subprocess.run([sys.executable, str(HERE.parents[1] / "build_html.py"), "--bank", str(HERE)], capture_output=True, text=True, check=True).stdout
    sha = out.split("material_sha256")[1].split()[0]
    n_bad = sum(not k["faithful"] for k in key.values())
    (HERE / "key.json").write_text(json.dumps({
        "schema": "meaning-trial-key-v1", "bank": BANK, "material_sha256": sha,
        "targets": {"catch_rate_min": 0.9, "false_alarm_rate_max": 0.1, "source": "docs/PLAN.md node V5 (same thresholds as K1); a signal, not a gate"},
        "about": "faithful = the tool's own echo of the unmutated composition tree (by construction, not by a person's judgement); "
                 "not faithful = the echo of the tree after one mechanical mutation (mutate.py), against the original sentence. "
                 f"{n_bad} of {len(key)} items are mutated. Explanations and disagreeing cases were written by the bank builder, a model.",
        "provenance": {"generator": "slice/slicegen/vocab.py Compiler.rule and Compiler.echo_rule, through trials/sentences/work/slice",
                       "vocabulary_sha256": voc_sha, "shuffle_seed": SEED,
                       "mutations": {k: (v.__doc__ or "") for k, v in mutate.KINDS.items()} | {"_": mutate.__doc__}},
        "items": key}, indent=1, ensure_ascii=False) + "\n")
    (HERE / "item_flags.json").write_text(json.dumps({
        "schema": "meaning-trial-flags-v1",
        "about": "Items the bank builder thinks a reader may fairly flag although the echo is the tool's own. 'key-debatable' items are also left out of one "
                 "row of the sensitivity table in REPORT.md; 'review' items are only listed. This file gives parts of the key away: keep it with key.json.",
        "flags": dict(sorted(flags.items()))}, indent=1, ensure_ascii=False) + "\n")
    (HERE / "responses").mkdir(exist_ok=True)
    kinds = {}
    for k in key.values():
        kinds[k["error_kind"]] = kinds.get(k["error_kind"], 0) + 1
    print(f"{len(items)} items, {n_bad} mutated ({100 * n_bad / len(items):.0f}%): {kinds}")
    print(f"material_sha256 {sha}")
    print(f"longest echo {max(len(i['second']) for i in items)} characters; median {sorted(len(i['second']) for i in items)[len(items) // 2]}")


if __name__ == "__main__":
    main()
